    ('b4357b01-a483-4b2b-b667-68e0a6e6f500'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd4-2026-10-04a-s001-rollback:b4357b01-a483-4b2b-b667-68e0a6e6f500:period_name', 'rollback of fields-wd4-2026-10-04a-s001: period_name None restored on Gradište Archaeological Site, Iđoš', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4000) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0016)", "decision": "replace", "status": "MISSING", "reasoning": "The intermunicipal heritage register describes this very locality, 7 km north-west of Kikinda in the direction of Iđoš, and says it was still inhabited in the Neolithic, with Neolithic settlement remains at its highest point. The fortified settlement itself is dated there to the end of the Bronze Age and the beginning of the Iron Age, so the Neolithic is the earliest period the site was in use and thus its start. The register gives periods only, no year.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('b4357b01-a483-4b2b-b667-68e0a6e6f500'::uuid, 'period_start', '-4000', NULL, 'fields-wd4-2026-10-04a-s001-rollback:b4357b01-a483-4b2b-b667-68e0a6e6f500:period_start', 'rollback of fields-wd4-2026-10-04a-s001: period_start None restored on Gradište Archaeological Site, Iđoš', '[{"source": "https://www.heritage-su.org.rs/en/archeological-site-gradiste/", "url": "https://www.heritage-su.org.rs/en/archeological-site-gradiste/", "quote": "It is located about 7 km northwest of Kikinda, in the direction of Idojos. It is a fortified settlement with ramparts from the land of the land, known as the “Slovenian town”. It was still inhabited in Neolithic, and with interruptions the life took place until the early Middle Ages.", "outcome": "found"}, {"source": "https://www.heritage-su.org.rs/en/archeological-site-gradiste/", "url": "https://www.heritage-su.org.rs/en/archeological-site-gradiste/", "quote": "The remains of the Neolithic settlement were found above the very mouth of the river, at the narrowest and highest point of Gradiste and in the surrounding area.", "outcome": "found"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0016)", "decision": "replace", "status": "MISSING", "reasoning": "The intermunicipal heritage register describes this very locality, 7 km north-west of Kikinda in the direction of Iđoš, and says it was still inhabited in the Neolithic, with Neolithic settlement remains at its highest point. The fortified settlement itself is dated there to the end of the Bronze Age and the beginning of the Iron Age, so the Neolithic is the earliest period the site was in use and thus its start. The register gives periods only, no year.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('b4d35f13-0f0e-479e-84a1-e388dda01d4d'::uuid, 'period_name', '1000 - 1500 AD', NULL, 'fields-wd4-2026-10-04a-s001-rollback:b4d35f13-0f0e-479e-84a1-e388dda01d4d:period_name', 'rollback of fields-wd4-2026-10-04a-s001: period_name None restored on Mawk''allaqta, Paruro', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1438) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0010)", "decision": "replace", "status": "MISSING", "reasoning": "The national inventory record of the Zona Arqueologica de Maukallaqta states that the site belongs to the middle Inca horizon, so the period word inca names this site''s own period and the year is read from the vocabulary.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
