    ('b4d35f13-0f0e-479e-84a1-e388dda01d4d'::uuid, 'site_type', 'Archaeological site', NULL, 'fields-wd4-2026-10-04a-s001-rollback:b4d35f13-0f0e-479e-84a1-e388dda01d4d:site_type', 'rollback of fields-wd4-2026-10-04a-s001: site_type None restored on Mawk''allaqta, Paruro', '[{"source": "https://en.wikipedia.org/wiki/Mawk%27allaqta,_Paruro", "url": "https://en.wikipedia.org/wiki/Mawk%27allaqta,_Paruro", "quote": "is an archaeological site in Peru", "outcome": "found"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0010)", "decision": "replace", "status": "MISSING", "reasoning": "The English article calls the site an archaeological site in Peru; the inventory record types it as an archaeological zone, and although it tags the record ''Templos'', its own description is a large settlement of recintos with a central plaza, so no narrower type is safely sourced.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
