    ('ba2e3e1a-f3d0-4c41-9508-946ceced696a'::uuid, 'site_type', 'Archaeological site', NULL, 'fields-wd4-2026-10-04a-s001-rollback:ba2e3e1a-f3d0-4c41-9508-946ceced696a:site_type', 'rollback of fields-wd4-2026-10-04a-s001: site_type None restored on Purunllacta, Soloco', '[{"source": "https://en.wikipedia.org/wiki/Purunllacta,_Soloco", "url": "https://en.wikipedia.org/wiki/Purunllacta,_Soloco", "quote": "is an archaeological site in Peru", "outcome": "found"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0012)", "decision": "replace", "status": "MISSING", "reasoning": "The field is empty and the article describes Purunllacta in Soloco District, Amazonas, as an archaeological site, which is the canonical type that fits; no more specific canonical type is stated for it.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
