    ('c928294a-3522-4b13-b6ab-1721bebbeb2a'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd4-2026-10-04a-s001-rollback:c928294a-3522-4b13-b6ab-1721bebbeb2a:period_name', 'rollback of fields-wd4-2026-10-04a-s001: period_name None restored on Židovar', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2500) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0017)", "decision": "replace", "status": "MISSING", "reasoning": "The English article of the site itself (Zidovar near Vrsac) dates its earliest archaeological layer to the early Bronze Age, before the Vatin, Belegis, Bosut-Basarabi and La Tene phases; that is a period the source names for this site, so the year is read from the vocabulary.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
