    ('ccf1b82b-6822-40ba-adf3-07913b155b7b'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd4-2026-10-04a-s001-rollback:ccf1b82b-6822-40ba-adf3-07913b155b7b:period_name', 'rollback of fields-wd4-2026-10-04a-s001: period_name None restored on Privlaka, Vukovar-Syrmia County', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-450) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "The article on Privlaka names the ancient site of the village as a Scordisci settlement of the late La Tène culture, excavated in the 1970s and 1980s, and La Tène is a period name the vocabulary holds. The Croatian Encyclopedia, for the owner''s awareness, describes the multi-layer hillfort-type settlement ''Gradina'' on the Bosut at the same place as founded and fortified in the Neolithic (Sopot culture) and inhabited through the Bronze Age, its visible remains belonging to the Late Iron Age (2nd/1st century BC) - so a Late Iron Age to La Tène start is what the excavation literature gives for the site as documented.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('ccf1b82b-6822-40ba-adf3-07913b155b7b'::uuid, 'period_start', '-450', NULL, 'fields-wd4-2026-10-04a-s001-rollback:ccf1b82b-6822-40ba-adf3-07913b155b7b:period_start', 'rollback of fields-wd4-2026-10-04a-s001: period_start None restored on Privlaka, Vukovar-Syrmia County', '[{"source": "https://en.wikipedia.org/wiki/Privlaka,_Vukovar-Syrmia_County", "url": "https://en.wikipedia.org/wiki/Privlaka,_Vukovar-Syrmia_County", "quote": "One Scordisci archaeological site in Privlaka dating back to late La Tène culture was excavated in the 1970s and 1980s", "outcome": "found"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "The article on Privlaka names the ancient site of the village as a Scordisci settlement of the late La Tène culture, excavated in the 1970s and 1980s, and La Tène is a period name the vocabulary holds. The Croatian Encyclopedia, for the owner''s awareness, describes the multi-layer hillfort-type settlement ''Gradina'' on the Bosut at the same place as founded and fortified in the Neolithic (Sopot culture) and inhabited through the Bronze Age, its visible remains belonging to the Late Iron Age (2nd/1st century BC) - so a Late Iron Age to La Tène start is what the excavation literature gives for the site as documented.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
