    ('f7f2dac5-0f0a-4cbd-8ac0-c2f1f42311ca'::uuid, 'period_start', '-300000', NULL, 'fields-wd4-2026-10-04a-s001-rollback:f7f2dac5-0f0a-4cbd-8ac0-c2f1f42311ca:period_start', 'rollback of fields-wd4-2026-10-04a-s001: period_start None restored on Pešturina', '[{"source": "https://en.wikipedia.org/wiki/Pe%C5%A1turina", "url": "https://en.wikipedia.org/wiki/Pe%C5%A1turina", "quote": "Artifacts from the Middle and Upper Paleolithic periods were discovered since the archaeological excavations began in 2006.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Pe%C5%A1turina", "url": "https://en.wikipedia.org/wiki/Pe%C5%A1turina", "quote": "The assemblage is dated to the Middle Paleolithic and as part of the Charentian Mousterian period, with Quina Mousterian elements.", "outcome": "found"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0016)", "decision": "replace", "status": "MISSING", "reasoning": "The article dates the Pešturina occupation to the Middle and Upper Paleolithic and dates the cave''s lowest, earliest assemblage to the Middle Paleolithic, so that is the start of the site''s history. Its absolute ages are given only in years before present (111,000 BP to 39,000 BP, 102,000 BP), which are not read as calendar years, so the period name is the dateable form.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('fce614a8-8697-45d3-9574-4b092231b0bd'::uuid, 'period_name', '< 4500 BC', NULL, 'fields-wd4-2026-10-04a-s001-rollback:fce614a8-8697-45d3-9574-4b092231b0bd:period_name', 'rollback of fields-wd4-2026-10-04a-s001: period_name None restored on El Mirón Cave', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-300000) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD4 decision (counted, round 1, wd4-r1-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "The excavators'' own institutional pages (University of New Mexico, Straus and González Morales) describe El Mirón Cave near Ramales de la Victoria as spanning from the last Neanderthals of the Middle Paleolithic to the Bronze Age, its project page naming the earliest levels as the late Mousterian, which is the Middle Paleolithic; the Spanish Wikipedia article agrees that the cave holds remains from the Musterian to the present. No source states a calendar year, century or millennium for the start, so the start is given as the period name ''middle paleolithic'' instead of a year.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('fce614a8-8697-45d3-9574-4b092231b0bd'::uuid, 'period_start', '-300000', NULL, 'fields-wd4-2026-10-04a-s001-rollback:fce614a8-8697-45d3-9574-4b092231b0bd:period_start', 'rollback of fields-wd4-2026-10-04a-s001: period_start None restored on El Mirón Cave', '[{"source": "https://anthropology.unm.edu/news-events/news/item/30-years-of-excavations-multidisciplinary-analyses-in-el-miron-cave-cantabria-spain.html", "url": "https://anthropology.unm.edu/news-events/news/item/30-years-of-excavations-multidisciplinary-analyses-in-el-miron-cave-cantabria-spain.html", "quote": "The site spans the period between the last Neanderthals of the Middle Paleolithic", "outcome": "found"}, {"source": "https://anthropology.unm.edu/research/field-projects/project/el-miron-cave.html", "url": "https://anthropology.unm.edu/research/field-projects/project/el-miron-cave.html", "quote": "Dr. Straus has been conducting excavation and field work at El Mirón Cave, located near Ramales, Cantabria, Spain, with his co-director, Professor Manuel Gonzalez Morales of the Universidad de Cantabria since 1996. The site, on the northern edge of the Cantabrian mountain chain, has yielded one of the longest prehistoric cultural sequences in Spain or Europe, with levels pertaining to the late Mousterian (Neanderthal culture), Gravettian, Solutrean, Magdalenian, Azilian, Neolithic, Chalcolithic, and Early Bronze ages", "outcome": "found"}, {"source": "WD4 decision (counted, round 1, wd4-r1-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "The excavators'' own institutional pages (University of New Mexico, Straus and González Morales) describe El Mirón Cave near Ramales de la Victoria as spanning from the last Neanderthals of the Middle Paleolithic to the Bronze Age, its project page naming the earliest levels as the late Mousterian, which is the Middle Paleolithic; the Spanish Wikipedia article agrees that the cave holds remains from the Musterian to the present. No source states a calendar year, century or millennium for the start, so the start is given as the period name ''middle paleolithic'' instead of a year.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('ff4dc88e-bebe-4b88-90d3-6697bffc9107'::uuid, 'period_name', '1000 - 1500 AD', NULL, 'fields-wd4-2026-10-04a-s001-rollback:ff4dc88e-bebe-4b88-90d3-6697bffc9107:period_name', 'rollback of fields-wd4-2026-10-04a-s001: period_name None restored on Huamanmarca, La Convención', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1438) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0008)", "decision": "replace", "status": "MISSING", "reasoning": "The Peruvian national tourism inventory''s record for this Wamanmarca (Huayopata, La Convencion, on the Cusco-Quillabamba road) calls the site''s Watunakuy rite a sacred Inca ceremony and describes the monument itself as of Inca origin, so the source gives the site''s own period.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('ff4dc88e-bebe-4b88-90d3-6697bffc9107'::uuid, 'period_start', '1438', NULL, 'fields-wd4-2026-10-04a-s001-rollback:ff4dc88e-bebe-4b88-90d3-6697bffc9107:period_start', 'rollback of fields-wd4-2026-10-04a-s001: period_start None restored on Huamanmarca, La Convención', '[{"source": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=6915", "url": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=6915", "quote": "la ceremonia mística del Watunakuy que es el encuentro sagrado inca que se realiza para honrar al ánima", "outcome": "found"}, {"source": "WD4 decision (counted, round 0, wd4-r0-b0008)", "decision": "replace", "status": "MISSING", "reasoning": "The Peruvian national tourism inventory''s record for this Wamanmarca (Huayopata, La Convencion, on the Cusco-Quillabamba road) calls the site''s Watunakuy rite a sacred Inca ceremony and describes the monument itself as of Inca origin, so the source gives the site''s own period.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 134;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _fields_wd4_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'WD4 field correction: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _fields_wd4_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'lat' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'lon' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'geom' THEN p.new_value::geometry IS NOT DISTINCT FROM p.old_value::geometry OR p.old_value IS NULL
                WHEN 'period_start' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'site_type' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'source_url' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD4 field correction: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _fields_wd4_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.old_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.old_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.old_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.old_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.old_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD4 field correction: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row undos a value this lane owns (old value)
    SELECT count(*) INTO bad FROM _fields_wd4_plan p
     WHERE CASE p.column_name
                WHEN 'period_name' THEN p.old_value NOT IN ('< 4500 BC', '4500 - 3000 BC', '3000 - 1500 BC', '1500 - 500 BC', '500 BC - 1 AD', '1 - 500 AD', '500 - 1000 AD', '1000 - 1500 AD', '1500+ AD')
                WHEN 'site_type' THEN p.old_value NOT IN ('City', 'Town', 'Village', 'Settlement', 'Urban', 'Villa', 'City/town/settlement', 'Residence/villa/farmhouse', 'City/town/settlement, Pyramid complex', 'Castle', 'Citadel', 'Fort', 'Fortress', 'Military', 'Wall', 'Gate', 'Fortress/citadel', 'Castle/palace', 'Gate/archway/bridge', 'Fortification', 'Church', 'Mosque', 'Temple', 'Monastery', 'Sacred site', 'Sanctuary', 'Religious', 'Temple complex', 'Church/cathedral', 'Minaret/tower', 'Stone cross', 'Cemetery', 'Necropolis', 'Tomb', 'Burial', 'Funerary', 'Necropolis/tombs complex', 'Barrow', 'Mound/tumulus', 'Cairn', 'Elongated skulls', 'Megalithic', 'Megalithic stones', 'Megalithic structures', 'Megalithic statues', 'Megalithic walls', 'Stone circle', 'Dolmen', 'Standing stone', 'Henge', 'Timber circle', 'Polygonal masonry', 'Cave', 'Cave Structures', 'Rock relief/carving', 'Rock art', 'Petroglyphs', 'Sculptured stone', 'Cave Structures, Rock art', 'Geoglyphs', 'Road', 'Bridge', 'Mine', 'Quarry', 'Infrastructure', 'Road/avenue/trackway', 'Reservoir/aqueduct/canal', 'Mine/quarry', 'Earthwork', 'Well', 'Aqueduct', 'Bath', 'Harbor', 'Port', 'Underwater structures', 'Shipwreck', 'Monument', 'Memorial', 'Stadium', 'Theater', 'Theatre', 'Forum', 'Palace', 'Pyramid complex', 'Museum', 'Amphitheatre', 'Scheduled monument', 'Heritage site', 'Archaeological site', 'Site', 'Ruin', 'Inscription', 'Natural feature', 'Impact crater', 'Geological interest', 'Magnetic anomaly', 'Unknown')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD4 field correction: % planned row(s) undo a value this lane does not own', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _fields_wd4_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WD4/structured-fields', '2026-10-04a_fields-wd4-s001-rollback', r.change_key, 'one_source', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'WD4 field correction: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _fields_wd4_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.new_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.new_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.new_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD4 field correction: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _fields_wd4_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-10-04a_fields-wd4-s001-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD4 field correction: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-04a_fields-wd4-s001-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD4 field correction: this run stamp journalled % row(s) outside unified_sites.(lat, lon, geom, period_start, period_name, site_type, source_url)', bad;
    END IF;

    RAISE NOTICE 'WD4 field correction: % of % planned cell(s) changed and journalled over 68 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-10-04a_fields-wd4-s001-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WD4/structured-fields'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-10-04a_fields-wd4-s001-rollback' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'lat' THEN u.lat IS NOT DISTINCT FROM l.new_value::double precision
                WHEN 'lon' THEN u.lon IS NOT DISTINCT FROM l.new_value::double precision
                WHEN 'geom' THEN u.geom IS NOT DISTINCT FROM l.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS NOT DISTINCT FROM l.new_value::integer
                WHEN 'period_name' THEN u.period_name IS NOT DISTINCT FROM l.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS NOT DISTINCT FROM l.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS NOT DISTINCT FROM l.new_value::text
                ELSE false END)
UNION ALL
SELECT 'curated rows whose period_name is not the bucket of period_start', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND period_name IS DISTINCT FROM (CASE WHEN period_start IS NULL THEN NULL WHEN period_start < -4500 THEN '< 4500 BC' WHEN period_start < -3000 THEN '4500 - 3000 BC' WHEN period_start < -1500 THEN '3000 - 1500 BC' WHEN period_start < -500 THEN '1500 - 500 BC' WHEN period_start < 1 THEN '500 BC - 1 AD' WHEN period_start < 500 THEN '1 - 500 AD' WHEN period_start < 1000 THEN '500 - 1000 AD' WHEN period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END)
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
